block masks:
  assert ctMaskZero(0'u32) == 0xFFFFFFFF'u32
  assert ctMaskZero(1'u32) == 0'u32
  assert ctMaskZero(0x80000000'u32) == 0'u32
  assert ctMaskNonZero(0xFFFFFFFF'u32) == 0xFFFFFFFF'u32
  assert ctMaskEq(5'u32, 5'u32) == 0xFFFFFFFF'u32
  assert ctMaskEq(5'u32, 4'u32) == 0'u32
  assert ctSelect(0xFFFFFFFF'u32, 1'u32, 2'u32) == 1'u32
  assert ctSelect(0'u32, 1'u32, 2'u32) == 2'u32
  let a = big("100000000")
  let b = big("ffffffff")
  assert ctLessMask(b.limbs, a.limbs, 2) == 0xFFFFFFFF'u32
  assert ctLessMask(a.limbs, b.limbs, 2) == 0'u32
  assert ctLessMask(a.limbs, a.limbs, 2) == 0'u32
  assert ctEqualMask(a.limbs, a.limbs, 2) == 0xFFFFFFFF'u32
  assert ctEqualMask(a.limbs, b.limbs, 2) == 0'u32
  var l = default(Limbs)
  assert ctFromBytesBE([0'u8, 0, 0, 0, 1, 2, 3, 4, 5], l)
  assert l[0] == 0x02030405'u32 and l[1] == 0x00000001'u32 and l[2] == 0'u32
  assert not ctFromBytesBE([], l)
  echo "masks ok"

block mul_vectors:
  var count = 0
  for v in MulVectors:
    let m = big(v[0])
    let ctx = ctInitMont(m)
    assert same(ctModMul(ctx, big(v[1]).limbs, big(v[2]).limbs), m.n, big(v[3])), v[0]
    inc count
  echo "modmul ", count

block sub_vectors:
  var count = 0
  for v in SubVectors:
    let m = big(v[0])
    let ctx = ctInitMont(m)
    assert same(ctModSub(ctx, big(v[1]).limbs, big(v[2]).limbs), m.n, big(v[3])), v[0]
    inc count
  echo "modsub ", count

block pow_vectors:
  var count = 0
  for v in PowVectors:
    let m = big(v[0])
    let ctx = ctInitMont(m)
    let e = big(v[2])
    let b = ctToMont(ctx, big(v[1]).limbs)
    # the exponent read over the modulus width, as for a CRT exponent
    assert same(ctFromMont(ctx, ctMontPow(ctx, b, e.limbs, m.n)), m.n, big(v[3])), v[0]
    # and over its own width, as for the public `e`
    assert same(ctFromMont(ctx, ctMontPow(ctx, b, e.limbs, e.n)), m.n, big(v[3])), v[0]
    inc count
  echo "modpow ", count

block mod_vectors:
  var count = 0
  for v in ModVectors:
    let m = big(v[0])
    let x = big(v[1])
    let ctx = ctInitMont(m)
    assert same(ctMod(ctx, x.limbs, x.n), m.n, big(v[2])), v[0]
    inc count
  echo "mod ", count

block fermat_inverse:
  var count = 0
  for v in InvVectors:
    let p = big(v[0])
    let ctx = ctInitMont(p)
    var pm2 = p.limbs
    var two = default(Limbs)
    two[0] = 2'u32
    discard ctSub(pm2, two, p.n)
    let a = big(v[1])
    let inv = ctFromMont(ctx, ctMontPow(ctx, ctToMont(ctx, a.limbs), pm2, p.n))
    assert same(inv, p.n, big(v[2])), v[0]
    assert same(ctModMul(ctx, a.limbs, inv), p.n, big("1")), v[0]
    inc count
  echo "inverse ", count

block product_vectors:
  var count = 0
  for v in ProdVectors:
    let h = int(big(v[0]).limbs[0])
    if h >= 1 and h <= (MaxLimbs - 2) div 2:
      assert cmp(ctMul(big(v[1]).limbs, big(v[2]).limbs, h), big(v[3])) == 0, v[1]
      inc count
  echo "product ", count

proc next(s: var uint64): uint32 =
  # xorshift64*: reproducible operands for the sweep against `bignum`
  s = s xor (s shr 12)
  s = s xor (s shl 25)
  s = s xor (s shr 27)
  result = uint32((s * 0x2545F4914F6CDD1D'u64) shr 32)

block sweep_against_bignum:
  var seed = 0x9E3779B97F4A7C15'u64
  var count = 0
  for iter in 0 ..< 200:
    var n = 1 + int(next(seed) mod 8'u32)
    if iter mod 40 == 0: n = 32
    var m = BigNum(limbs: default(Limbs), n: n)
    var base = BigNum(limbs: default(Limbs), n: n)
    var e = BigNum(limbs: default(Limbs), n: n)
    for i in 0 ..< n:
      m.limbs[i] = next(seed)
      base.limbs[i] = next(seed)
      e.limbs[i] = next(seed)
    m.limbs[0] = m.limbs[0] or 1'u32
    m.limbs[n-1] = m.limbs[n-1] or 0x10'u32
    if n == 1: m.limbs[0] = m.limbs[0] or 0x100'u32
    base.limbs[n-1] = base.limbs[n-1] mod m.limbs[n-1]
    var pub = default(Mont)
    assert initMont(m, pub)
    let want = modExp(base, e, pub)
    let ctx = ctInitMont(m)
    let got = ctFromMont(ctx, ctMontPow(ctx, ctToMont(ctx, base.limbs), e.limbs, n))
    assert same(got, n, want), "sweep " & $iter
    inc count
  echo "sweep ", count

proc blindBytes(len: int; seed: uint64): seq[byte] =
  var s = seed
  result = newSeq[byte](len)
  for i in 0 ..< result.len: result[i] = byte(next(s) and 0xFF'u32)

block crt_private_matches_openssl:
  var count = 0
  for k in CrtKeys:
    let p = big(k.p)
    let q = big(k.q)
    let qInv = big(k.qInv)
    var key = default(RsaCrt)
    assert initRsaCrt(big(k.n), big(k.e), p, q, big(k.dP), big(k.dQ), qInv, key), k.name
    assert rsaCrtModBytes(key) == (big(k.n).bitLen + 7) div 8
    let width = rsaCrtBlindLen(key)
    assert width == 4 * p.n + 8
    var ones = newSeq[byte](width)
    for i in 0 ..< ones.len: ones[i] = 0xFF'u8
    let blinds = [(blindBytes(width, 1'u64), blindBytes(width, 2'u64)),
                  (ones, ones), (@[7'u8], @[0xF1'u8])]
    for sg in k.sigs:
      for bl in blinds:
        var s = default(BigNum)
        assert rsaCrtPrivate(key, big(sg[0]), bl[0], bl[1], s), k.name
        assert cmp(s, big(sg[1])) == 0, k.name
        inc count
    # a zero blinding factor makes the output wrong: the fault check refuses
    var s = default(BigNum)
    let zeros = newSeq[byte](width)
    assert not rsaCrtPrivate(key, big(k.sigs[0][0]), zeros, blindBytes(width, 3'u64), s)
    assert s.isZero
    # wrong blinding shapes and an input outside [0, n)
    assert not rsaCrtPrivate(key, big(k.sigs[0][0]), @[], @[], s)
    assert not rsaCrtPrivate(key, big(k.sigs[0][0]), @[1'u8], @[1'u8, 2'u8], s)
    assert not rsaCrtPrivate(key, big(k.n), @[1'u8], @[2'u8], s)
    # the fault check on its own
    assert rsaCrtCheck(key, big(k.sigs[1][1]), big(k.sigs[1][0]))
    assert not rsaCrtCheck(key, big(k.sigs[1][1]), big(k.sigs[0][0]))
    # a wiped key no longer signs
    wipe(key)
    assert not rsaCrtPrivate(key, big(k.sigs[0][0]), @[1'u8], @[2'u8], s)
  echo "crt ", count

block crt_faults:
  let k = CrtKeys[0]
  let n = big(k.n)
  let e = big(k.e)
  let p = big(k.p)
  let q = big(k.q)
  let dP = big(k.dP)
  let dQ = big(k.dQ)
  let qInv = big(k.qInv)
  var key = default(RsaCrt)
  var s = default(BigNum)
  let c = big(k.sigs[0][0])
  # a corrupted dP, dQ or qInv parses but must not sign
  var bad = dP
  bad.limbs[3] = bad.limbs[3] xor 0x40'u32
  assert initRsaCrt(n, e, p, q, bad, dQ, qInv, key)
  assert not rsaCrtPrivate(key, c, @[1'u8], @[2'u8], s)
  assert s.isZero
  bad = dQ
  bad.limbs[0] = bad.limbs[0] xor 2'u32
  assert initRsaCrt(n, e, p, q, dP, bad, qInv, key)
  assert not rsaCrtPrivate(key, c, @[1'u8], @[2'u8], s)
  bad = qInv
  bad.limbs[5] = bad.limbs[5] xor 1'u32
  assert initRsaCrt(n, e, p, q, dP, dQ, bad, key)
  assert not rsaCrtPrivate(key, c, @[1'u8], @[2'u8], s)
  # p * q != n, swapped roles, even factors and a wrong exponent are refused
  bad = q
  bad.limbs[0] = bad.limbs[0] + 2'u32
  assert not initRsaCrt(n, e, p, bad, dP, dQ, qInv, key)
  bad = p
  bad.limbs[0] = bad.limbs[0] xor 1'u32
  assert not initRsaCrt(n, e, bad, q, dP, dQ, qInv, key)
  assert not initRsaCrt(n, big("10000"), p, q, dP, dQ, qInv, key)
  assert not initRsaCrt(n, big("1"), p, q, dP, dQ, qInv, key)
  assert not initRsaCrt(n, e, p, big("3"), dP, dQ, qInv, key)
  # swapping p and q is a different, still valid CRT key once qInv matches;
  # with the old qInv the fault check catches it
  assert initRsaCrt(n, e, q, p, dQ, dP, qInv, key)
  assert not rsaCrtPrivate(key, c, @[1'u8], @[2'u8], s)
  echo "faults ok"
